import json
import re

with open('vllm/model_executor/layers/quantization/awq_triton.py', 'r') as f:
    lines = f.readlines()

def extract_kernel(start_pattern):
    in_kernel = False
    kernel_lines = []
    for i, line in enumerate(lines):
        if re.search(start_pattern, line):
            in_kernel = True
        if in_kernel:
            kernel_lines.append(line)
            # Check if next line is empty or continues but we need to stop at next top-level def (no indent)
            if i+1 < len(lines):
                next_line = lines[i+1]
                if next_line.strip() and not next_line.startswith((' ', '\t', '@')):
                    # Next line is a new top-level definition (starts with letter)
                    # but need to ensure we're not catching nested lines.
                    # Simpler: stop when we see a line that starts with 'def ' and is not part of the kernel.
                    # Since kernels are only one level deep, we can stop when we see a line with indent 0 and starts with 'def' or '@'
                    pass
    # This is crude; let's use regex on whole content
    pass

content = ''.join(lines)
# Find awq_dequantize_kernel
dequant_match = re.search(r'(@triton\.jit\s*def awq_dequantize_kernel\(.*?\):.*?)(?=\n@|\ndef awq_gemm_kernel|\n#)', content, re.DOTALL)
if dequant_match:
    dequant = dequant_match.group(1).rstrip()
    print('dequant length', len(dequant))
else:
    print('dequant not found')
# Find awq_gemm_kernel
gemm_match = re.search(r'(@triton\.jit\s*def awq_gemm_kernel\(.*?\):.*?)(?=\n@|\ndef awq_gemm_triton|\n#)', content, re.DOTALL)
if gemm_match:
    gemm = gemm_match.group(1).rstrip()
    print('gemm length', len(gemm))
else:
    print('gemm not found')

output = {
    "vllm/model_executor/layers/quantization/awq_triton.py": {
        "awq_dequantize_kernel": dequant,
        "awq_gemm_kernel": gemm
    }
}
with open('/tmp/prediction.json', 'w') as f:
    json.dump(output, f, indent=2)
EOF
